            unavailable();
          } else {
            ready(terms);
          }
        },
        error: unavailable,
      });
  }

  private applyTerms(terms: Terms) {
    const previous = this.terms();
    if (previous && !this.sameTerms(previous, terms)) {
      this.consent.set(null);
      this.changed.set(true);
    }
